WITH cleaned AS (SELECT *, SUBSTRING(store_name, 1, 3) AS store_name_prefix FROM stores WHERE region IS NOT NULL), deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY region ORDER BY opened_date DESC, id) AS row_num FROM cleaned) x WHERE row_num = 1), kept AS (SELECT s.* FROM deduped s WHERE EXISTS (SELECT 1 FROM store_sales c WHERE c.store_id = s.id AND c.units IS NOT NULL)), scored AS (SELECT *, MIN(sqft) OVER w_grp AS running_min_sqft, AVG(sqft) OVER w_grp AS running_avg_sqft, COUNT(sqft) OVER w_grp AS running_count_sqft, SUM(sqft) OVER w_grp_2 AS cumulative_sqft FROM kept WINDOW w_grp AS (PARTITION BY region ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_grp_2 AS (PARTITION BY city, region ORDER BY row_num, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), remaining_keys AS (SELECT region FROM scored INTERSECT ALL SELECT region FROM stores WHERE opened_date BETWEEN '2024-08-07' AND '2025-10-01'), reconciled AS (SELECT s.* FROM scored s INNER JOIN remaining_keys k ON s.region = k.region), kept_keys AS (SELECT city FROM reconciled EXCEPT DISTINCT SELECT city FROM stores WHERE sqft >= 8910), verified AS (SELECT s.* FROM reconciled s INNER JOIN kept_keys k ON s.city = k.city), metrics AS (SELECT id, running_count_sqft, MIN(running_avg_sqft) OVER (PARTITION BY region) AS region_min_running_avg_sqft FROM verified) SELECT CASE WHEN running_count_sqft >= 16 THEN 'LARGE' ELSE 'SMALL' END AS running_count_sqft_tier, CASE WHEN region_min_running_avg_sqft >= 13329 THEN 'PREMIUM' ELSE 'STANDARD' END AS region_min_running_avg_sqft_tier, APPROX_PERCENTILE(region_min_running_avg_sqft, 0.95) AS region_min_running_avg_sqft_p95, AVG(running_count_sqft) AS avg_running_count_sqft, APPROX_PERCENTILE(region_min_running_avg_sqft, 0.9) AS region_min_running_avg_sqft_p90, APPROX_PERCENTILE(running_count_sqft, 0.9) AS running_count_sqft_p90 FROM metrics GROUP BY CASE WHEN running_count_sqft >= 16 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN region_min_running_avg_sqft >= 13329 THEN 'PREMIUM' ELSE 'STANDARD' END;
